/**
 * Writes the SQL that seeds form_templates from content/form-templates.ts.
 *   npm run db:gen-templates -- db/migrations/0005_seed_form_templates.sql
 * Idempotent SQL (ON CONFLICT DO NOTHING), so it is safe to re-run.
 */
import { writeFileSync } from "node:fs";
import { SEED_TEMPLATES } from "../content/form-templates";

const out = process.argv[2];
if (!out) throw new Error("Usage: gen-template-migration <output.sql>");

const lit = (value: string) => `'${value.replace(/'/g, "''")}'`;

const header =
  "-- Draft record templates (version 1) for clinician review. Generated by\n" +
  "-- scripts/gen-template-migration.ts from content/form-templates.ts; do not edit by hand.\n";
const lines: string[] = [];
for (const t of SEED_TEMPLATES) {
  lines.push(
    `INSERT INTO "form_templates" ("therapy_id", "stage", "version", "title", "schema", "status")\n` +
      `SELECT "id", ${lit(t.stage)}, ${t.version}, ${lit(t.title)}, ${lit(JSON.stringify(t.schema))}::jsonb, 'draft' FROM "therapies" WHERE "slug" = ${lit(t.slug)}\n` +
      `ON CONFLICT ("therapy_id", "stage", "version") DO NOTHING;`,
  );
}
writeFileSync(out, header + lines.join("\n--> statement-breakpoint\n") + "\n");
console.log(`Wrote ${SEED_TEMPLATES.length} templates to ${out}`);
